SELECT w.label, FLOOR(TIMESTAMPDIFF(MICROSECOND, w.s, m.observed_at)/2000000)*2 AS obs_bucket_s, COUNT(*) AS events, COUNT(DISTINCT m.symbol) AS symbols, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at))/1000) AS avg_lag_ms, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at))/1000) AS max_lag_ms, SUM(m.symbol='BTCUSDT') AS btc_events FROM (SELECT 'P137' AS label, CAST('2026-10-11 21:00:00' AS DATETIME(6)) AS s, CAST('2026-10-11 21:00:20' AS DATETIME(6)) AS e UNION ALL SELECT 'P143', CAST('2026-10-11 22:43:00' AS DATETIME(6)), CAST('2026-10-11 22:43:45' AS DATETIME(6)) UNION ALL SELECT 'P158', CAST('2026-10-12 03:30:00' AS DATETIME(6)), CAST('2026-10-12 03:30:12' AS DATETIME(6)) UNION ALL SELECT 'P172', CAST('2026-10-12 07:15:00' AS DATETIME(6)), CAST('2026-10-12 07:15:50' AS DATETIME(6)) UNION ALL SELECT 'P182', CAST('2026-10-12 10:05:00' AS DATETIME(6)), CAST('2026-10-12 10:05:25' AS DATETIME(6))) w JOIN crypto_ai.market_price_event m ON m.source='BINANCE_KLINE_DIRECT_FIX153' AND m.delivery_status IN ('APPLIED','NON_CANONICAL','PROTECTION_NOT_APPLIED','PENDING') AND m.created_at BETWEEN w.s AND DATE_ADD(w.e, INTERVAL 20 SECOND) AND m.observed_at BETWEEN w.s AND w.e GROUP BY w.label, obs_bucket_s ORDER BY w.label, obs_bucket_s LIMIT 200